import * as React from 'react';
import * as MagneticButtonPrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface MagneticButtonProps extends React.ComponentPropsWithoutRef<typeof MagneticButtonPrimitive.MagneticButton> {
  className?: string;
}

export const MagneticButton = React.forwardRef<HTMLDivElement, MagneticButtonProps>(
  ({ className, children, ...props }, ref) => (
    <MagneticButtonPrimitive.MagneticButton
      ref={ref}
      className={clsx(
        'relative inline-flex items-center justify-center rounded-xl bg-primary px-6 py-3 font-semibold text-primary-foreground shadow-md transition-shadow hover:shadow-lg cursor-pointer will-change-transform',
        className
      )}
      {...props}
    >
      {children}
    </MagneticButtonPrimitive.MagneticButton>
  )
);
MagneticButton.displayName = 'MagneticButton';

