solid.code:
import { Component, JSX, splitProps } from 'solid-js';
import * as MagneticButtonPrimitive from '@exhuma/core';

export interface MagneticButtonProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const MagneticButton: Component<MagneticButtonProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <MagneticButtonPrimitive.MagneticButton
      class={`relative inline-flex items-center justify-center rounded-xl bg-primary px-6 py-3 font-semibold text-primary-foreground shadow-md transition-shadow hover:shadow-lg cursor-pointer will-change-transform ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </MagneticButtonPrimitive.MagneticButton>
  );
};

