import { MagneticButton } from '@exhuma/core';

class ExhumaMagneticButtonElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-magnetic-button');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-magnetic-button')) {
  customElements.define('exhuma-magnetic-button', ExhumaMagneticButtonElement);
}

