import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as MagneticButtonPrimitive from '@exhuma/core';

export interface MagneticButtonProps extends ViewProps {
  children?: React.ReactNode;
}

export function MagneticButton({ style, children, ...props }: MagneticButtonProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

